const emojiChoices=[
['😀','خنده شاد خوشحال smile happy'],['😃','خنده شاد لبخند grin'],['😄','خنده خندان laugh'],['😁','لبخند ذوق grin'],['😆','خنده بلند laugh'],['🤣','قهقهه خنده rofl'],['😂','اشک خنده خنده tears joy'],['🙂','لبخند ساده smile'],['🙃','وارونه شوخی silly'],['😉','چشمک wink'],['😊','لبخند مهربان blush'],['😇','فرشته angel'],['🥰','عاشقانه عشق قلب love'],['😍','عاشق قلب چشم قلبی heart eyes'],['😘','بوسه بوس kiss'],['😋','خوشمزه مزه yummy'],['😎','عینک خونسرد cool'],['🤩','ستاره ذوق عالی star struck'],['🥳','جشن تولد party'],['😭','گریه اشک sad'],['😢','ناراحت غمگین cry'],['😡','عصبانی خشم angry'],['🤔','فکر فکرکردن سوچ thinking'],['🤗','آغوش بغل hug'],['🙏','ممنون لطف خواهش دعا thanks please'],['👏','تشویق دست clap'],['👍','پسند خوب تایید like thumbs up'],['👎','نپسند بد thumbs down'],['💪','قدرت قوی muscle'],['🤝','همکاری توافق handshake'],['❤️','قلب عشق قرمز heart love'],['🧡','قلب نارنجی orange heart'],['💛','قلب زرد yellow heart'],['💚','قلب سبز green heart'],['💙','قلب آبی blue heart'],['💜','قلب بنفش purple heart'],['🖤','قلب سیاه black heart'],['🤍','قلب سفید white heart'],['💔','قلب شکسته broken heart'],['✨','درخشش جرقه ستاره sparkle'],['⭐','ستاره star'],['🔥','آتش عالی خفن fire'],['🎉','جشن تبریک party tada'],['🎁','هدیه کادو gift'],['✅','تایید درست انجام شد check'],['❌','خطا نادرست اشتباه cross'],['⚠️','هشدار اخطار warning'],['💡','ایده لامپ light bulb'],['🚀','موشک شروع launch rocket'],['🌱','رشد طبیعت جوانه seedling'],['☀️','خورشید روز آفتاب sun'],['🌙','ماه شب moon'],['☕','قهوه چای نوشیدنی coffee'],['🍕','پیتزا غذا pizza'],['🍰','کیک شیرینی cake'],['🐱','گربه cat'],['🐶','سگ dog'],['🌸','گل شکوفه flower'],['🎨','هنر طراحی نقاشی art'],['📌','سنجاق پین pin'],['📍','مکان موقعیت location'],['📧','ایمیل نامه email'],['📞','تلفن تماس phone'],['💬','گفتگو پیام chat'],['🔔','زنگ اعلان notification'],['🔒','قفل امنیت lock'],['🔍','جستجو ذره بین search'],['📷','دوربین عکس camera'],['🎵','موسیقی نت music'],['🏆','جایزه برنده trophy'],['💯','صد عالی hundred']
