function renderEmojiResults(){const query=emojiSearch.value.trim().toLocaleLowerCase();const matches=emojiChoices.filter(([,keywords])=>!query||keywords.toLocaleLowerCase().includes(query));emojiResults.replaceChildren();if(!matches.length){const empty=document.createElement('span');empty.id='emoji-empty';empty.textContent=@js($ffCanvas('no_emoji'));emojiResults.append(empty);return}for(const [emoji,keywords] of matches){const button=document.createElement('button');button.type='button';button.setAttribute('role','option');button.setAttribute('aria-label',keywords.split(' ').slice(0,3).join(' '));button.title=keywords.split(' ').slice(0,3).join(' · ');button.textContent=emoji;button.dataset.emoji=emoji;emojiResults.append(button)}}
renderEmojiResults();emojiSearch.addEventListener('input',renderEmojiResults);emojiToggle.addEventListener('click',()=>{emojiPicker.hidden=!emojiPicker.hidden;emojiToggle.setAttribute('aria-expanded',String(!emojiPicker.hidden));if(!emojiPicker.hidden){emojiSearch.value='';renderEmojiResults();emojiSearch.focus({preventScroll:true})}});
function clean(html,htmlBlock=false){const t=document.createElement('template');t.innerHTML=html;t.content.querySelectorAll('.ff-node-grip,[data-ff-editor-only]').forEach(control=>control.remove());const tags=['DIV','P','BR','STRONG','B','EM','I','U','S','STRIKE','SUB','SUP','UL','OL','LI','H2','H3','H4','BLOCKQUOTE','PRE','CODE','SPAN','A'];if(htmlBlock)tags.push('SECTION','ARTICLE','MAIN','HEADER','FOOTER','ASIDE','NAV','H1','H5','H6','TABLE','THEAD','TBODY','TFOOT','TR','TH','TD','CAPTION','FIGURE','FIGCAPTION','IMG','DL','DT','DD','HR','DETAILS','SUMMARY');const values={'data-align':['left','right','center','justify'],'data-tone':['indigo','red','green','muted'],'data-size':['small','large','huge'],'data-direction':['rtl','ltr']};function walk(parent){for(const el of [...parent.children]){if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH'].includes(el.tagName)){el.remove();continue}walk(el);if(!tags.includes(el.tagName)){el.replaceWith(...el.childNodes);continue}for(const attr of [...el.attributes]){if(htmlBlock){if(['id','title','lang','alt'].includes(attr.name))continue;if(attr.name==='dir'&&['rtl','ltr'].includes(attr.value))continue;if(['colspan','rowspan','width','height'].includes(attr.name)&&/^\d{1,4}$/.test(attr.value))continue;if(['href','src'].includes(attr.name)&&/^(?:https?:\/\/|mailto:|tel:|#|\/(?!\/)|\.{1,2}\/)[^\s<>\\]*$/i.test(attr.value))continue}if(values[attr.name]?.includes(attr.value))continue;if(attr.name==='data-color'&&/^#[0-9a-f]{6}$/i.test(attr.value))continue;if(el.tagName==='A'&&attr.name==='href'&&/^(https?:\/\/|mailto:|#[a-z0-9_-]*$)/i.test(attr.value))continue;el.removeAttribute(attr.name)}if(/^#[0-9a-f]{6}$/i.test(el.getAttribute('data-color')||''))el.style.color=el.getAttribute('data-color')}}walk(t.content);return t.innerHTML}
const menu=document.getElementById('menu');function closeMenu(){menu.style.display='none'}
function openMenu(node,x,y){finish();menuNode=node.dataset.node;port.postMessage({type:'select',id:menuNode});menu.querySelector('[data-action=editInline]').hidden=false;for(const el of menu.querySelectorAll('[data-action]'))el.disabled=menuNode==='root'&&['remove','duplicate','up','down','parent'].includes(el.dataset.action);menu.style.display='block';menu.style.left=Math.max(8,Math.min(x,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-menu.offsetHeight-8))+'px';menu.querySelector('button:not([disabled]):not([hidden])')?.focus({preventScroll:true})}
menu.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;closeMenu();if(action==='editInline')edit(menuNode);else port.postMessage({type:'contextAction',id:menuNode,action})});
menu.addEventListener('keydown',e=>{const items=[...menu.querySelectorAll('button:not([disabled]):not([hidden])')];const i=items.indexOf(document.activeElement);if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus()}if(e.key==='Escape')closeMenu()});
document.addEventListener('pointerdown',e=>{if(!menu.contains(e.target))closeMenu()});addEventListener('scroll',closeMenu,true);addEventListener('resize',closeMenu);
function remember(){const selection=getSelection();if(editing&&selection.rangeCount&&editing.contains(selection.anchorNode))savedRange=selection.getRangeAt(0).cloneRange()}
