function logicalAxisBefore(event,target){const parent=target.parentElement?.closest('[data-node]');if(!parent)return event.clientY<target.getBoundingClientRect().top+target.getBoundingClientRect().height/2;const style=getComputedStyle(parent);const horizontal=parent.dataset.type==='grid'||parent.dataset.type==='columns'||(style.display==='flex'&&style.flexDirection.startsWith('row'));if(!horizontal)return event.clientY<target.getBoundingClientRect().top+target.getBoundingClientRect().height/2;const rect=target.getBoundingClientRect();return style.direction==='rtl'?event.clientX>rect.left+rect.width/2:event.clientX<rect.left+rect.width/2}
function placement(event,target){const rect=target.getBoundingClientRect();if(canContain(target)){const horizontal=target.dataset.type==='grid'||target.dataset.type==='columns'||(getComputedStyle(target).display==='flex'&&getComputedStyle(target).flexDirection.startsWith('row'));const axis=horizontal?event.clientX-rect.left:event.clientY-rect.top;const extent=horizontal?rect.width:rect.height;const before=horizontal?(getComputedStyle(target).direction==='rtl'?event.clientX>rect.right-24:event.clientX<rect.left+24):event.clientY<rect.top+24;const after=horizontal?(getComputedStyle(target).direction==='rtl'?event.clientX<rect.left+24:event.clientX>rect.right-24):event.clientY>rect.bottom-24;if(before)return 'before';if(after)return 'after';if(event.target===target||extent<48)return 'inside';return 'inside'}return logicalAxisBefore(event,target)?'before':'after'}
document.addEventListener('dragover',event=>{if(!draggedNodeId)draggedNodeId=event.dataTransfer.getData('application/x-filaforge-node')||event.dataTransfer.getData('text/plain');if(!draggedNodeId)return;const target=event.target.closest('[data-node]');if(!target||target.dataset.node===draggedNodeId||document.querySelector('[data-node="'+CSS.escape(draggedNodeId)+'"]')?.contains(target)){clearDropMarker();return}event.preventDefault();event.dataTransfer.dropEffect='move';if(dropNode&&dropNode!==target)clearDropMarker();dropNode=target;dropPosition=placement(event,target);target.dataset.dropPosition=dropPosition});
document.addEventListener('drop',event=>{if(!draggedNodeId||!dropNode)return;event.preventDefault();event.stopPropagation();port?.postMessage({type:'move',id:draggedNodeId,targetId:dropNode.dataset.node,position:dropPosition});clearDrop()});
window.addEventListener('message',e=>{if(e.source!==parent)return;if(e.data?.type==='filaforge-drag-start')draggedNodeId=e.data.id;if(e.data?.type==='filaforge-drag-end'&&draggedNodeId===e.data.id)clearDrop()});
window.addEventListener('message',e=>{if(e.source!==parent||e.data!=='filaforge-connect'||!e.ports[0])return;port?.close();port=e.ports[0];port.onmessage=({data})=>{if(data.type==='media'){mediaURLs=data.urls;return}if(data.type==='icons'){iconCatalog=data.icons;return}if(data.type==='render'){if(editing){port.postMessage({type:'rendered',version:data.version});return;}doc=data.document;selected=data.selected;dynamicLabels=data.labels||{};editorFonts=Object.fromEntries((data.fonts||[]).map(font=>[font.id,font]));editorFontDefault=data.fontDefault;previewMode=!!data.preview;document.body.classList.toggle('ff-preview',previewMode);document.documentElement.dir=doc.direction;document.documentElement.lang=doc.locale;const pageMain=document.querySelector('main');pageMain.replaceChildren(draw(doc.root));responsiveRules(doc.root);fontRules(doc.root);if(previewMode)pageMain.scrollTop=0;const el=document.querySelector('[data-node="'+CSS.escape(selected)+'"]');if(el)el.dataset.selected='true';port.postMessage({type:'rendered',version:data.version})}if(data.type==='preview'){previewMode=!!data.enabled;document.body.classList.toggle('ff-preview',previewMode)}if(data.type==='flush'){finish();port.postMessage({type:'flushed'})}if(data.type==='edit'&&!previewMode)edit(data.id);if(data.type==='drop'&&!previewMode){const target=document.elementFromPoint(data.x,data.y)?.closest('[data-node]');if(target&&canContain(target))port.postMessage({type:'insert',parent:target.dataset.node,widget:data.widget})}};port.postMessage({type:'ready'})});
</script></body></html>
